//! Cross-validates this crate's independent, hand-rolled decoder against
//! containers encoded by the already round-trip-tested Node prototype (see
//! `fixtures.rs`, generated by `node prototype/scripts/gen-rust-fixtures.js`)
//! — catching the class of bug a single implementation checking itself
//! against itself never can.

use super::fixtures::*;
use super::*;

const WIFI_KNOWN_KEYS: &[u64] = &[0, 1, 2, 4, 6];

#[test]
fn wifi_record_routes_and_fields_extract() {
    let container = Container::parse(WIFI_CONTAINER).expect("valid container");
    assert_eq!(container.version, 1);

    let records: Vec<_> = container.records().collect::<Result<_, _>>().unwrap();
    assert_eq!(records.len(), 1);
    let rec = &records[0];
    assert_eq!(rec.tag, Some(100));
    assert_eq!(rec.type_id, Some(100));
    assert!(!rec.aborted);

    let outcome = check_criticality(rec.map_bytes, WIFI_KNOWN_KEYS, |_| {
        panic!("no odd keys here")
    })
    .unwrap();
    assert_eq!(outcome, CriticalityOutcome::Ok);

    let ssid = find_value(rec.map_bytes, 2).unwrap().unwrap();
    assert_eq!(read_definite_string(ssid).unwrap(), b"My Coffee Shop");
    let password = find_value(rec.map_bytes, 4).unwrap().unwrap();
    assert_eq!(read_definite_string(password).unwrap(), b"guest123");
}

#[test]
fn untagged_wifi_record_still_routes_via_key_0() {
    let container = Container::parse(WIFI_UNTAGGED_CONTAINER).unwrap();
    let records: Vec<_> = container.records().collect::<Result<_, _>>().unwrap();
    assert_eq!(records[0].tag, None);
    assert_eq!(records[0].type_id, Some(100));
    assert!(!records[0].aborted);
}

#[test]
fn unrecognized_even_key_aborts_the_record() {
    let container = Container::parse(WIFI_UNKNOWN_EVEN_KEY_CONTAINER).unwrap();
    let records: Vec<_> = container.records().collect::<Result<_, _>>().unwrap();
    let rec = &records[0];
    assert!(!rec.aborted); // routing itself succeeds; criticality is a separate, Record-Type-specific check

    let outcome = check_criticality(rec.map_bytes, WIFI_KNOWN_KEYS, |_| {
        panic!("must not reach an odd key")
    })
    .unwrap();
    assert_eq!(outcome, CriticalityOutcome::Aborted(8));
}

#[test]
fn unrecognized_odd_key_is_silently_ignored() {
    let container = Container::parse(WIFI_UNKNOWN_ODD_KEY_CONTAINER).unwrap();
    let records: Vec<_> = container.records().collect::<Result<_, _>>().unwrap();
    let rec = &records[0];

    let mut ignored = Vec::new();
    let outcome = check_criticality(rec.map_bytes, WIFI_KNOWN_KEYS, |k| ignored.push(k)).unwrap();
    assert_eq!(outcome, CriticalityOutcome::Ok);
    assert_eq!(ignored, vec![9]);

    // Rest of the record is still fully usable.
    let ssid = find_value(rec.map_bytes, 2).unwrap().unwrap();
    assert_eq!(read_definite_string(ssid).unwrap(), b"SSID");
}

#[test]
fn hardware_parity_mismatch_aborts_at_routing_time() {
    let container = Container::parse(HARDWARE_PARITY_MISMATCH_CONTAINER).unwrap();
    let records: Vec<_> = container.records().collect::<Result<_, _>>().unwrap();
    let rec = &records[0];
    assert!(rec.aborted);
    assert_eq!(
        rec.abort_reason,
        Some(AbortReason::HardwareParityMismatch {
            tag: 105,
            key0: 100
        })
    );
}

#[test]
fn missing_key_zero_aborts_at_routing_time() {
    let container = Container::parse(MISSING_KEY0_CONTAINER).unwrap();
    let records: Vec<_> = container.records().collect::<Result<_, _>>().unwrap();
    let rec = &records[0];
    assert!(rec.aborted);
    assert_eq!(rec.abort_reason, Some(AbortReason::MissingKeyZero));
}

#[test]
fn one_aborted_record_does_not_affect_its_sibling() {
    let container = Container::parse(TWO_RECORD_CONTAINER).unwrap();
    let records: Vec<_> = container.records().collect::<Result<_, _>>().unwrap();
    assert_eq!(records.len(), 2);

    let first = check_criticality(records[0].map_bytes, WIFI_KNOWN_KEYS, |_| {}).unwrap();
    assert_eq!(first, CriticalityOutcome::Aborted(8));

    assert_eq!(records[1].type_id, Some(900));
    assert!(!records[1].aborted);
    let payload = find_value(records[1].map_bytes, 2).unwrap().unwrap();
    assert_eq!(read_definite_string(payload).unwrap(), b"sibling record");
}

#[test]
fn ndef_path_bare_sequence_with_no_magic_still_routes() {
    // Strip the 5-byte magic/version prefix and decode the bare CBOR
    // Sequence directly, simulating the NDEF MIME-typed path (§2).
    let bare_seq = &WIFI_CONTAINER[5..];
    assert!(
        Container::parse(bare_seq).is_err(),
        "must not look like a valid magic-prefixed container"
    );

    let records: Vec<_> = records_from_sequence(bare_seq)
        .collect::<Result<_, _>>()
        .unwrap();
    assert_eq!(records[0].type_id, Some(100));
}

#[test]
fn bad_magic_and_wrong_version_are_rejected() {
    let mut bad_magic = WIFI_CONTAINER.to_vec();
    bad_magic[0] = 0x00;
    assert_eq!(Container::parse(&bad_magic).err(), Some(Error::BadMagic));

    let mut bad_version = WIFI_CONTAINER.to_vec();
    bad_version[4] = 0x02;
    assert_eq!(
        Container::parse(&bad_version).err(),
        Some(Error::UnsupportedVersion(2))
    );
}

#[test]
fn skip_value_rejects_pathologically_deep_nesting() {
    // MAX_DEPTH array nestings of empty arrays, one level too deep: each
    // byte 0x81 is "array of 1 item" (major 4, info 1); the final 0x80 is
    // an empty array (major 4, info 0) terminating the chain.
    let mut deep = alloc_free_deep_array(cbor::MAX_DEPTH as usize + 1);
    deep.push(0x80);
    assert_eq!(
        cbor::skip_value(&deep, cbor::MAX_DEPTH),
        Err(cbor::Error::TooDeep)
    );

    // One level shallower must succeed.
    let mut ok_depth = alloc_free_deep_array(cbor::MAX_DEPTH as usize - 1);
    ok_depth.push(0x80);
    assert!(cbor::skip_value(&ok_depth, cbor::MAX_DEPTH).is_ok());
}

fn alloc_free_deep_array(depth: usize) -> Vec<u8> {
    // test-only helper; std's Vec is fine here even though the library
    // itself is no_std, since #[cfg(test)] builds link std regardless.
    core::iter::repeat_n(0x81u8, depth).collect()
}
